class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change #1: EF 9 removes "Discriminator" property from documents
            // when only one entity type maps to a container. Existing documents still have it,
            // so we must explicitly configure it to read old data.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Blog");

            // Breaking change #2: EF 9 changes default id format from "EntityType|Key"
            // to just the key value. Existing documents use "Blog|1" format, so preserve it.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<BlogIdGenerator>();

            // Breaking change #3: Cosmos DB does not support indexes defined via EF Core
            // in the same way. HasIndex() now throws by default in EF 9 for Cosmos provider.
            // Remove the HasIndex call; use Cosmos indexing policy on the container instead.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

