using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Fix #1 – Discriminator removal:
            // EF 9 no longer adds a "Discriminator" property when a single entity maps
            // to a container. Existing documents have "$type" or "Discriminator", so
            // explicitly re-enable it to keep reading/writing old documents.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Blog");

            // Fix #2 – Id format change:
            // EF 9 uses just the key as the JSON "id" (e.g. "1"), but existing docs
            // use the EF 8 format "Blog|1". Preserve legacy format via id property config.
            entity.Property(b => b.Id).HasValueGeneratorFactory<LegacyIdFactory>();

            // Fix #3 – HasIndex not supported on Cosmos:
            // EF 9 now throws for HasIndex on the Cosmos provider.
            // Removed the previous HasIndex(b => b.Name) call.
            // Define indexes via the Cosmos container's indexing policy instead.
        });
    }
}

/// <summary>
/// Preserves the EF 8 "Discriminator|Key" id format for existing Cosmos documents.
/// </summary>
class LegacyIdFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(
        Microsoft.EntityFrameworkCore.Metadata.IProperty property,
        Microsoft.EntityFrameworkCore.Metadata.ITypeBase typeBase)
        => new LegacyIdGenerator();
}

class LegacyIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    protected override string GenerateNext(EntityEntry entry)
        => $"Blog|{entry.Property("Id").CurrentValue}";
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

