class SyncJob
{
    void Run(BlogContext context)
    {
        // Fix #4 – Raw SQL queries:
        // If you have raw SQL like: SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // This still works ONLY because we re-enabled the Discriminator property above.
        // Without that fix, new documents wouldn't have the property and the query would
        // return incomplete results. With the discriminator configured, this remains valid.
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

